import csv,sqlite3
from collections import defaultdict
with open('csv/frpm.csv') as f:
    frpm_by_cds = {r['CDSCode']: r for r in csv.DictReader(f)}
with open('csv/frpm.csv') as f:
    districts = set(r['District Name'] for r in csv.DictReader(f) if 'Riverside' in r['District Name'] or 'Riverside' in r['County Name'])
conn = sqlite3.connect('db/satscores.db')
cur = conn.cursor()
by_district = defaultdict(list)
dist_info = {}
for row in cur.execute("SELECT cds, sname, AvgScrMath FROM satscores").fetchall():
    cds, sname, avg_math = row
    school_info = frpm_by_cds.get(cds)
    if school_info:
        dname = school_info['District Name']
        if dname in districts:
            by_district[dname].append(avg_math)
            if dname not in dist_info:
                dist_info[dname] = school_info.get('Charter Funding Type', '')
result = []
for d, scores in by_district.items():
    avg = sum(scores) / len(scores)
    if avg > 400:
        result.append((d, dist_info[d], avg))
result.sort(key=lambda x: -x[2])
for r in result:
    print(f'{r[0]}: avg={r[2]:.1f}, funding={r[1]}')
print(f'Total districts: {len(result)}')

